import numpy as np


def generate_spatial_bounding_box(img, margin=0, return_slice=False):
    arr = np.asarray(img)
    if arr.ndim > 0 and arr.shape[0] == 1:
        arr = arr[0]
    coords = np.argwhere(arr != 0)
    if coords.size == 0:
        starts = np.zeros(arr.ndim, dtype=int)
        ends = np.asarray(arr.shape, dtype=int)
    else:
        starts = np.maximum(coords.min(axis=0) - margin, 0)
        ends = np.minimum(coords.max(axis=0) + margin + 1, np.asarray(arr.shape))
